"""Full signed tables generated by Sage's independent legacy S-box machinery."""

import json
from pathlib import Path

import pytest

from claasp.semantics.cryptanalysis import SBoxTransitionSemantics

TABLES = {
    "PRESENT": (12, 5, 6, 11, 9, 0, 10, 13, 3, 14, 15, 8, 4, 7, 1, 2),
    "Heys": (14, 4, 13, 1, 2, 15, 11, 8, 3, 10, 6, 12, 5, 9, 0, 7),
    "rectangular_3_to_2": (0, 1, 2, 3, 1, 0, 3, 2),
}
DATA = json.loads(Path("tests/fixtures/legacy_parity/sbox_tables.json").read_text())


@pytest.mark.parametrize("name", TABLES)
def test_complete_ddt_and_signed_walsh_tables_match_current_legacy(name):
    semantics = SBoxTransitionSemantics(TABLES[name])
    assert semantics.difference_distribution_table() == tuple(
        tuple(row) for row in DATA[name]["ddt"]
    )
    assert semantics.walsh_correlation_table() == tuple(tuple(row) for row in DATA[name]["walsh"])


EXTENDED = json.loads(Path("tests/fixtures/legacy_parity/extended_sboxes.json").read_text())


@pytest.mark.parametrize("name", EXTENDED["boxes"])
def test_aes_and_all_eight_rectangular_des_signed_tables(name):
    case = EXTENDED["boxes"][name]
    semantics = SBoxTransitionSemantics(case["table"])
    assert semantics.difference_distribution_table() == tuple(tuple(row) for row in case["ddt"])
    assert semantics.walsh_correlation_table() == tuple(tuple(row) for row in case["walsh"])
